panels.script:
(function () {
  var NS = 'pack-market';
  var ACCENT = '#b4632a';
  var BORDER = '#d5cbb9';
  var BG = '#fffdf8';
  var INK = '#3a332a';
  var MUTED = '#8a7c66';

  var host =
    (document.currentScript && document.currentScript.parentElement) ||
    document.querySelector('[data-namespace="' + NS + '"]') ||
    document.body;

  var wrap = document.createElement('div');
  wrap.className = 'pack-market-panel';
  wrap.style.cssText =
    'font:12px system-ui,-apple-system,"Segoe UI",sans-serif;' +
    'background:' + BG + ';border:1px solid ' + BORDER + ';border-radius:6px;' +
    'padding:8px;color:' + INK + ';box-sizing:border-box;';

  var bar = document.createElement('div');
  bar.style.cssText = 'display:flex;gap:6px;align-items:center;';

  var input = document.createElement('input');
  input.type = 'text';
  input.placeholder = '搜索包：名字 / 描述 / 标签';
  input.style.cssText =
    'flex:1 1 auto;min-width:0;font:12px system-ui;padding:5px 7px;' +
    'border:1px solid ' + BORDER + ';border-radius:4px;background:#fff;' +
    'color:' + INK + ';outline:none;';
  input.addEventListener('focus', function () { input.style.borderColor = ACCENT; });
  input.addEventListener('blur', function () { input.style.borderColor = BORDER; });

  var btn = document.createElement('button');
  btn.type = 'button';
  btn.textContent = '搜索';
  btn.style.cssText =
    'font:12px system-ui;padding:5px 12px;border:1px solid ' + ACCENT + ';' +
    'border-radius:4px;background:' + ACCENT + ';color:' + BG + ';cursor:pointer;';

  var status = document.createElement('div');
  status.style.cssText = 'margin-top:6px;color:' + MUTED + ';min-height:14px;';

  var list = document.createElement('div');
  list.style.cssText = 'margin-top:6px;display:flex;flex-direction:column;gap:6px;';

  bar.appendChild(input);
  bar.appendChild(btn);
  wrap.appendChild(bar);
  wrap.appendChild(status);
  wrap.appendChild(list);
  host.appendChild(wrap);

  // 高度：不能用 document.body.getBoundingClientRect().height（结果列表可能绝对定位会漏），
  // 改为遍历所有可见元素取 max(bottom)。
  function measureHeight() {
    var max = 0;
    var nodes = document.querySelectorAll('body *');
    for (var i = 0; i < nodes.length; i++) {
      var node = nodes[i];
      if (!node.getBoundingClientRect) continue;
      var cs = window.getComputedStyle(node);
      if (!cs) continue;
      if (cs.display === 'none' || cs.visibility === 'hidden' || cs.position === 'fixed') continue;
      var r = node.getBoundingClientRect();
      if (r.width === 0 && r.height === 0) continue;
      var bottom = r.bottom + (window.scrollY || window.pageYOffset || 0);
      if (bottom > max) max = bottom;
    }
    return Math.ceil(max);
  }

  function reportHeight() {
    var h = measureHeight();
    wrap.setAttribute('data-height', String(h));
    try {
      if (window.ngu && typeof window.ngu.resize === 'function') {
        window.ngu.resize(NS, h);
      } else if (window.parent && window.parent !== window) {
        window.parent.postMessage({ type: 'ngu:panel-height', namespace: NS, height: h }, '*');
      }
    } catch (e) { /* 宿主没有高度接口就忽略 */ }
    return h;
  }

  function call(tool, args) {
    return window.ngu.call('mcp_call', { server: NS, tool: tool, args: args });
  }

  function textOf(payload) {
    if (!payload) return '';
    if (typeof payload === 'string') return payload;
    if (payload.error && payload.error.message) return payload.error.message;
    var c = payload.content;
    if (c && c[0] && typeof c[0].text === 'string') return c[0].text;
    if (typeof payload.message === 'string') return payload.message;
    return '';
  }

  function dataOf(payload) {
    var text = textOf(payload);
    if (!text) return null;
    try { return JSON.parse(text); } catch (e) { return { raw: text }; }
  }

  function note(msg, isError) {
    status.textContent = msg;
    status.style.color = isError ? '#a3321f' : MUTED;
    reportHeight();
  }

  function el(tag, css, text) {
    var node = document.createElement(tag);
    if (css) node.style.cssText = css;
    if (text != null) node.textContent = text;
    return node;
  }

  function renderPacks(packs) {
    list.textContent = '';
    if (!packs.length) {
      list.appendChild(el('div', 'color:' + MUTED + ';padding:4px 0;', '没有匹配的包。'));
      reportHeight();
      return;
    }
    packs.forEach(function (p) {
      var row = el('div',
        'border:1px solid ' + BORDER + ';border-radius:5px;padding:6px 8px;' +
        'background:#fff;display:flex;gap:8px;align-items:flex-start;');

      var left = el('div', 'flex:1 1 auto;min-width:0;');
      left.appendChild(el('div', 'font-weight:600;color:' + ACCENT + ';word-break:break-all;',
        String(p.name || '(未命名)') + (p.version ? '  ' + p.version : '')));
      left.appendChild(el('div', 'margin-top:2px;color:' + INK + ';word-break:break-word;',
        p.description || ''));
      if (p.tags && p.tags.length) {
        left.appendChild(el('div', 'margin-top:3px;color:' + MUTED + ';font-size:11px;',
          (Array.isArray(p.tags) ? p.tags : []).join(' · ')));
      }

      var dl = el('button',
        'font:12px system-ui;padding:4px 10px;white-space:nowrap;flex:0 0 auto;' +
        'border:1px solid ' + ACCENT + ';border-radius:4px;background:' + BG + ';' +
        'color:' + ACCENT + ';cursor:pointer;', '下载');
      dl.type = 'button';
      dl.addEventListener('click', function () {
        dl.disabled = true;
        dl.style.opacity = '0.55';
        dl.textContent = '下载中';
        note('正在下载 ' + (p.name || '') + ' …', false);
        call('market_install', { name: p.name })
          .then(function (res) {
            var failed = !!(res && res.isError);
            var data = dataOf(res) || {};
            if (failed) {
              note(textOf(res) || '下载失败', true);
            } else {
              note('已下载到 ' + (data.path || '') +
                (data.matched ? '（sha256 校验通过）' : '（索引无 sha256，未校验）') +
                '。只下载，未安装。', false);
            }
          })
          .catch(function (e) {
            note('下载失败：' + ((e && e.message) || e), true);
          })
          .then(function () {
            dl.disabled = false;
            dl.style.opacity = '1';
            dl.textContent = '下载';
            reportHeight();
          });
      });

      row.appendChild(left);
      row.appendChild(dl);
      list.appendChild(row);
    });
    reportHeight();
  }

  var busy = false;
  function doSearch() {
    if (busy) return;
    busy = true;
    btn.disabled = true;
    var query = input.value.trim();
    note('搜索中 …', false);
    call('market_search', { query: query, limit: 10 })
      .then(function (res) {
        var failed = !!(res && res.isError);
        var data = dataOf(res);
        if (failed) {
          list.textContent = '';
          note(textOf(res) || '搜索失败', true);
          return;
        }
        var packs = (data && data.packs) || (Array.isArray(data) ? data : []);
        var total = data && typeof data.total === 'number' ? data.total : packs.length;
        note('共 ' + total + ' 个结果' +
          (packs.length < total ? '，显示前 ' + packs.length + ' 个' : '') +
          (query ? '（关键词：' + query + '）' : ''), false);
        renderPacks(packs);
      })
      .catch(function (e) {
        list.textContent = '';
        note('搜索失败：' + ((e && e.message) || e), true);
      })
      .then(function () {
        busy = false;
        btn.disabled = false;
        reportHeight();
      });
  }

  btn.addEventListener('click', doSearch);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') doSearch();
  });

  if (window.ngu && typeof window.ngu === 'object') {
    doSearch();
  }
  reportHeight();
  window.addEventListener('resize', reportHeight);
})();
